 p:{look:{age:"baby",sex:"ж",hair:"baby",hc:"#a5774d",skin:"jaundice",mood:"sleepy",marks:[],bg:"#f2e9d4"}, n:"Варя", age:"8 месяцев", sex:"ж", w:8, h:70},
