 intro:[["nurse", "Девочка 8 месяцев, температура 10 дней на трёх антибиотиках. Вялая, бледная, живот большой."],
        ["mom", "Со слов мамы, родители — двоюродные брат и сестра. Первый ребёнок в семье умер в 5 месяцев «от инфекции»."]],
 hx:{"open": [["nurse", "Девочка 8 месяцев, температура 10 дней на трёх антибиотиках. Вялая, бледная, живот большой."], ["mom", "Со слов мамы, температура не снижается."]], "limit": 9, "people": {"mom": "маму"}, "q": [{"g": "Жалобы", "t": "Сколько дней температура и что получала?", "kw": ["сколько", "дней", "давно", "антибиот", "лечени", "получал"], "v": "need", "a": {"mom": "Десять дней. Три антибиотика сменили — не помогает."}, "c": "Лихорадка без ответа на антибиотики — повод искать неинфекционную причину."}, {"g": "Жалобы", "t": "Были ли судороги, изменилось ли поведение?", "kw": ["судорог", "дёрга", "дерга", "поведен", "вял", "сонлив"], "v": "need", "a": {"mom": "Утром дёрнулась вся, минуту. И она стала какая-то сонная."}, "c": "Неврологические симптомы — поражение ЦНС при ГЛГ."}, {"g": "Жизнь и семья", "t": "Вы с мужем не родственники?", "kw": ["родств", "брат", "сестр", "кровн", "муж"], "v": "need", "a": {"mom": "(тихо, глядя в пол) Мы… двоюродные брат и сестра."}, "c": "Кровнородственный брак — риск аутосомно-рецессивных болезней, в том числе семейного ГЛГ."}, {"g": "Жизнь и семья", "t": "Есть ли у вас другие дети? Здоровы?", "kw": ["дети", "детей", "ребён", "первый", "умер"], "v": "need", "a": {"mom": "Первый сын умер в пять месяцев. Сказали — «инфекция»."}, "c": "Смерть сибса в младенчестве «от инфекции» — красный флаг семейного ГЛГ."}, {"g": "Жалобы", "t": "Была ли желтуха, сыпь, точечные кровоизлияния?", "kw": ["желт", "сыпь", "синяк", "кровот", "точк"], "v": "need", "a": {"mom": "Кожа желтоватая стала, на животе красные точки."}, "c": "Желтуха и петехии — поражение печени и тромбоцитопения."}, {"g": "Общее", "t": "Как ест, прибавляет ли в весе?", "kw": ["ест", "корм", "вес", "прибав", "сосёт", "сосет"], "v": "ok", "a": {"mom": "Плохо сосёт, вес встал."}, "c": "Тяжесть состояния."}, {"g": "Общее", "t": "Были ли контакты с больными, поездки на юг?", "kw": ["контакт", "поездк", "ездили", "юг"], "v": "ok", "a": {"mom": "Нет, никуда не ездили."}, "c": "Для исключения лейшманиоза и инфекций — триггеров вторичного ГЛГ."}, {"g": "Жизнь и семья", "t": "Прививки по возрасту?", "kw": ["привив", "вакцин"], "v": "no", "a": {"mom": "По возрасту, последняя в 6 месяцев."}, "c": "Не помогает диагнозу."}, {"g": "Жизнь и семья", "t": "Как прошли роды?", "kw": ["роды", "родил", "беремен"], "v": "no", "a": {"mom": "Нормально, в срок."}, "c": "Не помогает диагнозу."}]},
